"""
SportX Dataset Inspection Script
Audits raw Kaggle datasets in data/raw/ and generates a comprehensive inspection report.
"""
import os
import json
import pandas as pd
import numpy as np


def inspect_datasets():
    raw_dir = os.path.join("data", "raw")
    report_dir = os.path.join("data", "evaluation")
    os.makedirs(report_dir, exist_ok=True)
    
    report_lines = [
        "# SportX Biomechanics Dataset Inspection Report",
        "**Generated by**: `scripts/inspect_datasets.py`",
        f"**Date**: {pd.Timestamp.now().strftime('%Y-%m-%d %H:%M:%S')}",
        "---",
        "## 1. Overview of Raw Datasets in `data/raw/`\n"
    ]
    
    files = [f for f in os.listdir(raw_dir) if f.endswith(".csv")]
    report_lines.append(f"Found **{len(files)}** raw CSV datasets:\n")
    
    stats_dict = {}

    for f in sorted(files):
        path = os.path.join(raw_dir, f)
        size_mb = os.path.getsize(path) / (1024 * 1024)
        
        # Read sample or full file
        df = pd.read_csv(path)
        n_rows, n_cols = df.shape
        missing_count = int(df.isnull().sum().sum())
        duplicates = int(df.duplicated().sum())
        
        stats_dict[f] = {
            "size_mb": round(size_mb, 2),
            "rows": n_rows,
            "cols": n_cols,
            "missing_values": missing_count,
            "duplicates": duplicates,
            "columns": list(df.columns)
        }
        
        report_lines.append(f"### `{f}`")
        report_lines.append(f"- **File Size**: {size_mb:.2f} MB")
        report_lines.append(f"- **Dimensions**: {n_rows:,} rows × {n_cols} columns")
        report_lines.append(f"- **Missing Values**: {missing_count}")
        report_lines.append(f"- **Duplicate Rows**: {duplicates}")
        
        if "class" in df.columns:
            class_counts = df["class"].value_counts().to_dict()
            report_lines.append("- **Class Distribution**:")
            for cls_name, count in class_counts.items():
                report_lines.append(f"  - `{cls_name}`: {count:,} samples ({count/n_rows*100:.1f}%)")
        elif "Label" in df.columns:
            class_counts = df["Label"].value_counts().to_dict()
            report_lines.append("- **Label Distribution**:")
            for cls_name, count in class_counts.items():
                report_lines.append(f"  - `{cls_name}`: {count:,} frames ({count/n_rows*100:.1f}%)")
        elif "vid_id" in df.columns:
            n_vids = df["vid_id"].nunique()
            report_lines.append(f"- **Unique Video IDs**: {n_vids}")
            frames_per_vid = df.groupby("vid_id").size()
            report_lines.append(f"- **Frames per Video**: Mean = {frames_per_vid.mean():.1f}, Min = {frames_per_vid.min()}, Max = {frames_per_vid.max()}")
        
        report_lines.append("\n")

    # Save Markdown report
    md_path = os.path.join(report_dir, "dataset_inspection_report.md")
    with open(md_path, "w", encoding="utf-8") as f:
        f.write("\n".join(report_lines))
        
    # Save JSON report
    json_path = os.path.join(report_dir, "dataset_inspection_report.json")
    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(stats_dict, f, indent=2)

    print(f"Inspection complete! Report saved to {md_path}")


if __name__ == "__main__":
    inspect_datasets()
